{"command": "cat > /prediction.json << 'JSONEOF'
{
    "vllm/v1/spec_decode/utils.py": {
        "eagle_prepare_next_token_padded_kernel": "@triton.jit\ndef eagle_prepare_next_token_padded_kernel(\n    sampled_token_ids_ptr,  # [num_reqs, num_sampled_tokens_per_req]\n    discard_request_mask_ptr,  # [num_reqs]\n    backup_next_token_ids_ptr,  # [num_reqs]\n    next_token_ids_ptr,  # [num_reqs] (output)\n    valid_sampled_tokens_count_ptr,  # [num_reqs] (output)\n    vocab_size,  # tl.int32\n    num_sampled_tokens_per_req,  # tl.int32 (num_spec_tokens + 1)\n    num_reqs,  # tl.int32\n    stride_sampled_token_ids,  # tl.int32 (stride for dim 0)\n    BLOCK_SIZE_TOKENS: tl.constexpr,  # Power-of-2 >= num_sampled_tokens_per_req\n):\n    \"\"\"\n    Fused kernel to prepare next token IDs for padded speculative decoding.\n    \n    For each request:\n    1. Mask out sampled tokens if the request is discarded (set to -1)\n    2. Create valid mask (token != -1 and token < vocab_size)\n    3. Count valid tokens per request\n    4. Get the last valid token index\n    5. Select the last valid token, or use backup if no valid token exists\n    \n    Args:\n        sampled_token_ids_ptr: Input tensor [num_reqs, num_sampled_tokens_per_req]\n        discard_request_mask_ptr: Boolean mask [num_reqs], 1 if request should be discarded\n        backup_next_token_ids_ptr: Backup token IDs [num_reqs]\n        next_token_ids_ptr: Output next token IDs [num_reqs]\n        valid_sampled_tokens_count_ptr: Output count of valid tokens [num_reqs]\n        vocab_size: Vocabulary size\n        num_sampled_tokens_per_req: Number of sampled tokens per request\n        num_reqs: Number of requests\n        stride_sampled_token_ids: Stride for the first dimension\n        BLOCK_SIZE_TOKENS: Block size for token dimension (power of 2)\n    \"\"\"\n    req_idx = tl.program_id(0)\n    \n    if req_idx >= num_reqs:\n        return\n    \n    # Check if this request is discarded\n    is_discarded = tl.load(discard_request_mask_ptr + req_idx)\n    \n    # Load all tokens for this request\n    token_offsets = req_idx * stride_sampled_token_ids + tl.arange(0, BLOCK_SIZE_TOKENS)\n    mask = tl.arange(0, BLOCK_SIZE_TOKENS) < num_sampled_tokens_per_req\n    sampled_tokens = tl.load(sampled_token_ids_ptr + token_offsets, mask=mask, other=-1)\n    \n    # If request is discarded, set all tokens to -1\n    sampled_tokens = tl.where(is_discarded, -1, sampled_tokens)\n    \n    # Create valid mask: token != -1 and token < vocab_size\n    valid_mask = (sampled_tokens != -1) & (sampled_tokens < vocab_size)\n    \n    # Count valid tokens\n    valid_count = tl.sum(valid_mask.to(tl.int32))\n    \n    # Store valid count\n    tl.store(valid_sampled_tokens_count_ptr + req_idx, valid_count)\n    \n    # Find the last valid index by computing max position where valid\n    positions = tl.arange(0, BLOCK_SIZE_TOKENS)\n    weighted_positions = tl.where(valid_mask, positions, -1)\n    last_valid_idx = tl.max(weighted_positions, axis=0)\n    \n    # Get the last valid token or use backup\n    last_valid_idx_safe = tl.maximum(last_valid_idx, 0)\n    next_token = tl.load(sampled_token_ids_ptr + req_idx * stride_sampled_token_ids + last_valid_idx_safe)\n    backup_token = tl.load(backup_next_token_ids_ptr + req_idx)\n    \n    # Use last token if valid (last_valid_idx >= 0), otherwise use backup\n    next_token = tl.where(last_valid_idx >= 0, next_token, backup_token)\n    \n    # Store next token ID\n    tl.store(next_token_ids_ptr + req_idx, next_token)",
        "eagle_prepare_inputs_padded_kernel": "@triton.jit\ndef eagle_prepare_inputs_padded_kernel(\n    cu_num_draft_tokens_ptr,  # [num_reqs]\n    valid_sampled_tokens_count_ptr,  # [num_reqs]\n    query_start_loc_gpu_ptr,  # [num_reqs + 1]\n    token_indices_to_sample_ptr,  # [num_reqs] (output)\n    num_reqs,  # tl.int32\n):\n    \"\"\"\n    Fused kernel to prepare inputs for padded speculative decoding.\n    \n    For each request:\n    1. Compute num_draft_tokens from cu_num_draft_tokens (difference)\n    2. Compute num_rejected_tokens = where(num_draft_tokens > 0, \n                                          num_draft_tokens + 1 - valid_sampled_tokens_count, 0)\n    3. Compute token_indices_to_sample = query_start_loc[1:] - 1 - num_rejected_tokens\n    \n    Args:\n        cu_num_draft_tokens_ptr: Cumulative num draft tokens [num_reqs]\n        valid_sampled_tokens_count_ptr: Valid sampled tokens count [num_reqs]\n        query_start_loc_gpu_ptr: Query start locations [num_reqs + 1]\n        token_indices_to_sample_ptr: Output token indices to sample [num_reqs]\n        num_reqs: Number of requests\n    \"\"\"\n    req_idx = tl.program_id(0)\n    \n    if req_idx >= num_reqs:\n        return\n    \n    # Compute num_draft_tokens for this request\n    if req_idx == 0:\n        num_draft_tokens = tl.load(cu_num_draft_tokens_ptr + 0)\n    else:\n        cu_curr = tl.load(cu_num_draft_tokens_ptr + req_idx)\n        cu_prev = tl.load(cu_num_draft_tokens_ptr + req_idx - 1)\n        num_draft_tokens = cu_curr - cu_prev\n    \n    # Load valid sampled tokens count\n    valid_count = tl.load(valid_sampled_tokens_count_ptr + req_idx)\n    \n    # Compute num_rejected_tokens\n    num_rejected_tokens = tl.where(\n        num_draft_tokens > 0,\n        num_draft_tokens + 1 - valid_count,\n        0\n    )\n    \n    # Compute token_indices_to_sample = query_start_loc[req_idx + 1] - 1 - num_rejected_tokens\n    query_start_next = tl.load(query_start_loc_gpu_ptr + req_idx + 1)\n    token_idx_to_sample = query_start_next - 1 - num_rejected_tokens\n    \n    # Store result\n    tl.store(token_indices_to_sample_ptr + req_idx, token_idx_to_sample)"
    }
}
JSONEOF"}

